  | "org:update"
  | "org:delete"
  | "org:manage_billing"
  | "org:manage_flags"
  | "member:read"
  | "member:invite"
  | "member:update_role"
  | "member:remove"
  | "project:create"
  | "project:read"
  | "project:update"
  | "project:archive"
  | "project:delete"
  | "issue:create"
  | "issue:read"
  | "issue:update"
  | "issue:assign"
  | "issue:archive"
  | "issue:delete"
  | "comment:create"
  | "comment:read"
  | "comment:update"
  | "comment:delete"
  | "activity:read"
  | "activity:export"
  | "notification:read"
  | "notification:manage"
  | "webhook:manage";

