/**
 * The recorded owner offers the workspace to another active member. Only one
 * offer may be open at a time; the offered member is the only one alerted.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, "org:transfer_ownership", org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (pending) {
    if (!hasLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    // A lapsed offer is already closed; record that before it frees the slot.
    await handoverRepo.resolveHandover(
      orgId,
      pending.id,
      "expired",
      pending.expiresAt,
    );
  }

  const handover = await handoverRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: `You have been offered ownership of ${org.name}. Accept before ${handover.expiresAt} to take it over.`,
    href: "/settings",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the previous one steps down, so the workspace has an owner at every
 * instant and the last-owner rule never trips. Everything published here is
 * on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const now = new Date();
  const handover = await requireActionableHandover(actor, orgId, now);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const incoming = await memberRepo.findMember(orgId, actor.userId);
  if (!incoming) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  // Claim the offer before any role moves, so a racing second acceptance
  // finds nothing pending rather than repeating the handover.
  const claimed = await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(now),
  );
  if (!claimed) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const previousOwnerId = org.ownerId;

  if (incoming.role !== "owner") {
    await applyRoleChange(actor, incoming, "owner");
  }

  const updated = await orgRepo.updateOrgOwner(orgId, actor.userId);

  const outgoing = await memberRepo.findMember(orgId, previousOwnerId);
  if (outgoing && outgoing.role === "owner") {
    await assertLastOwnerRetained(orgId, outgoing.id, "admin");
    await applyRoleChange(actor, outgoing, "admin");
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: previousOwnerId,
    toUserId: actor.userId,
  });

  return updated;
}

/** The offered member turns the offer down; the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const now = new Date();
  const handover = await requireActionableHandover(actor, orgId, now);

  const declined = await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(now),
  );
  if (!declined) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return declined;
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, "org:transfer_ownership", org);

  const now = new Date();
  const open = await findOpenHandover(orgId, now);
  if (!open) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const canceled = await handoverRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    toIsoTimestamp(now),
  );
  if (!canceled) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return canceled;
}

/** The open offer, visible to every member of the workspace; `null` if none. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return findOpenHandover(orgId, new Date());
}

/** An offer made at T is open strictly before T + 7 days, and lapsed from then on. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

/** The pending offer unless it has lapsed — a lapsed offer is not open. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  return pending && !hasLapsed(pending, now) ? pending : null;
}

/**
 * The offer `actor` may accept or decline. Anyone but the offered member sees
 * nothing pending; the offered member is told when their offer has lapsed.
 */
async function requireActionableHandover(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}
