describe("acceptOwnershipHandover", () => {
  it("makes the offered member the owner and steps the previous owner down", async () => {
    const tenant = await createTenant("handover-accept");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    const org = await orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);

    expect(org.ownerId).toBe(tenant.userIds.viewer);
    const incoming = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const outgoing = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(incoming?.role).toBe("owner");
    expect(outgoing?.role).toBe("admin");

    expect(roleChanges).toHaveLength(2);
    expect(roleChanges).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          actorId: tenant.userIds.viewer,
          memberId: incoming!.id,
          from: "viewer",
          to: "owner",
        }),
        expect.objectContaining({
          actorId: tenant.userIds.viewer,
          memberId: outgoing!.id,
          from: "owner",
          to: "admin",
        }),
      ]),
    );
    expect(transfers).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.viewer,
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.viewer,
      }),
    ]);

    const audit = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.ownership_transferred"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      actorId: tenant.userIds.viewer,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.viewer },
    });

    expect(
      await refusal(orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id)),
    ).toBe("nothing_pending");
    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).toBeNull();
  });

  it("only changes the previous owner's role when the new owner already held the role", async () => {
    const tenant = await createTenant("handover-accept-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    const roleChanges = capture("member.role_changed");

    await orgService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    expect(roleChanges).toEqual([
      expect.objectContaining({ from: "owner", to: "admin" }),
    ]);
  });

  it("moves new-member alerts, billing and removability to the new owner", async () => {
    const tenant = await createTenant("handover-follows");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    await orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id);

    const newOwner = await actorFor(tenant, tenant.userIds.member);
    const previousOwner = await actorFor(tenant, tenant.userIds.owner);
    expect(newOwner.role).toBe("owner");
    expect(previousOwner.role).toBe("admin");

    const joiner = await userRepo.insertUser({
      email: "joiner@handover-follows.test",
      name: "Joiner",
      passwordHash: "seed",
    });
    const joined = await memberRepo.insertMember(tenant.org.id, joiner.id, "member", null);
    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: joiner.id,
      occurredAt: joined.createdAt,
      memberId: joined.id,
      userId: joiner.id,
      role: "member",
    });
    for (const [userId, expected] of [
      [tenant.userIds.member, 1],
      [tenant.userIds.owner, 0],
    ] as const) {
      const page = await listNotifications(newOwner, {
        orgId: tenant.org.id,
        recipientId: userId,
        unreadOnly: false,
        kind: ["member_joined"],
        limit: 25,
        cursor: null,
      });
      expect(page.items).toHaveLength(expected);
    }

    const plan = { orgId: tenant.org.id, plan: "enterprise", interval: "monthly" } as const;
    await expect(billingService.changePlan(previousOwner, plan)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(billingService.changePlan(tenant.actors.owner, plan)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(billingService.changePlan(newOwner, plan)).resolves.toMatchObject({
      plan: "enterprise",
    });

    await expect(
      orgService.initiateOwnershipHandover(previousOwner, tenant.org.id, tenant.userIds.admin),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const outgoing = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const removed = await memberService.removeMember(newOwner, {
      orgId: tenant.org.id,
      memberId: outgoing!.id,
    });
    expect(removed.archivedAt).not.toBeNull();
  });
});

describe("departure", () => {
  it("withdraws the offer when the offered member is removed", async () => {
    const tenant = await createTenant("handover-leave-to");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member!.id,
    });

    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).toBeNull();
    expect(
      await refusal(orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id)),
    ).toBe("nothing_pending");
  });

  it("withdraws the offer when the offering owner is removed", async () => {
    const tenant = await createTenant("handover-leave-from");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await memberService.removeMember(await actorFor(tenant, tenant.userIds.admin), {
      orgId: tenant.org.id,
      memberId: owner!.id,
    });

    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).toBeNull();
    expect(
      await refusal(orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id)),
    ).toBe("nothing_pending");
  });
});

