/**
 * Ownership handover: offer, accept, decline, withdraw, lapse.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function actorFor(tenant: Tenant, userId: UserId): Promise<Actor> {
  const actor = await memberService.resolveActor(userId, tenant.org.id);
  if (!actor) throw new Error("no live membership");
  return actor;
}

async function refusal(promise: Promise<unknown>): Promise<string> {
  const error: unknown = await promise.then(
    () => null,
    (reason: unknown) => reason,
  );
  expect(error).toBeInstanceOf(OwnershipHandoverError);
  return (error as OwnershipHandoverError).reason;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("initiateOwnershipHandover", () => {
  it("opens an offer that lapses seven days later and alerts only the offered member", async () => {
    const tenant = await createTenant("handover-offer");

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(WEEK_MS);

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const page = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        kind: ["ownership_handover"],
        limit: 25,
        cursor: null,
      });
      expect(page.items, role).toHaveLength(role === "member" ? 1 : 0);
    }

    const seenByViewer = await orgService.getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(seenByViewer).toEqual(offer);
  });

  it("is reserved to the recorded owner, not to anyone holding the owner role", async () => {
    const tenant = await createTenant("handover-second-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    const secondOwner = await actorFor(tenant, tenant.userIds.admin);

    await expect(
      orgService.initiateOwnershipHandover(secondOwner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    await expect(
      orgService.cancelOwnershipHandover(secondOwner, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses the owner themselves, unknown, foreign and removed users", async () => {
    const tenant = await createTenant("handover-targets");
    const other = await createTenant("handover-targets-other");
    const stranger = await userRepo.insertUser({
      email: "stranger@handover.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer!.id,
    });

    expect(
      await refusal(
        orgService.initiateOwnershipHandover(
          tenant.actors.owner,
          tenant.org.id,
          tenant.userIds.owner,
        ),
      ),
    ).toBe("self");

    for (const userId of [
      "01HZZZUNKNOWNUSER000000000" as UserId,
      stranger.id,
      other.userIds.member,
      tenant.userIds.viewer,
    ]) {
      await expect(
        orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
    }

    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.owner, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("allows one open offer at a time", async () => {
    const tenant = await createTenant("handover-one-open");
    const first = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(
      await refusal(
        orgService.initiateOwnershipHandover(
          tenant.actors.owner,
          tenant.org.id,
          tenant.userIds.admin,
        ),
      ),
    ).toBe("pending_exists");

    const withdrawn = await orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(withdrawn).toMatchObject({ id: first.id, status: "canceled" });
    expect(withdrawn.resolvedAt).not.toBeNull();
    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).toBeNull();
    expect(
      await refusal(orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)),
    ).toBe("nothing_pending");
    expect(
      await refusal(orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id)),
    ).toBe("nothing_pending");

    const second = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(second.id).not.toBe(first.id);
  });
});

describe("declineOwnershipHandover", () => {
  it("is only open to the offered member and frees the slot", async () => {
    const tenant = await createTenant("handover-decline");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    for (const actor of [tenant.actors.owner, tenant.actors.admin, tenant.actors.member]) {
      expect(await refusal(orgService.declineOwnershipHandover(actor, tenant.org.id))).toBe(
        "nothing_pending",
      );
      expect(await refusal(orgService.acceptOwnershipHandover(actor, tenant.org.id))).toBe(
        "nothing_pending",
      );
    }

    const declined = await orgService.declineOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();
    expect(
      await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).toBeNull();

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
  });
});

describe("lapse", () => {
